import csv


class CSVProcessor:

    SUCCESS = 1
    FAILURE = 0
    DEFAULT_DELIMITER = '.'
    PROCESS_SUFFIX = '_process.csv'

    def __init__(self):
        pass

    def read_csv(self, file_name):
        data = []
        with open(file_name, 'r') as file:
            reader = csv.reader(file)
            title = next(reader)
            for row in reader:
                data.append(row)
        return title, data

    def write_csv(self, data, file_name):
        try:
            with open(file_name, 'w', newline='') as file:
                writer = csv.writer(file)
                writer.writerows(data)
            return self.SUCCESS
        except Exception:
            return self.FAILURE

    def extract_column(self, data, column_index):
        return [row[column_index] for row in data]

    def uppercase_column(self, column_data):
        return [value.upper() for value in column_data]

    def build_processed_data(self, title, column_data):
        return [title, column_data]

    def get_processed_file_name(self, original_file_name):
        return original_file_name.split(self.DEFAULT_DELIMITER)[0] + self.PROCESS_SUFFIX

    def process_csv_data(self, column_index, save_file_name):
        title, data = self.read_csv(save_file_name)
        column_data = self.uppercase_column(self.extract_column(data, column_index))
        new_data = self.build_processed_data(title, column_data)
        processed_file_name = self.get_processed_file_name(save_file_name)
        return self.write_csv(new_data, processed_file_name)
